import math

# Gate and target definitions
TX_MIN, TX_MAX = 28.0, 32.0
TY_MIN, TY_MAX = 2.0, 5.0
G1_X, G1_Y_MIN, G1_Y_MAX = 13.0, 1.0, 2.8
G2_X, G2_Y_MIN, G2_Y_MAX = 23.0, 1.8, 3.0
TARGET_X, TARGET_Y = 30.0, 3.5

# Anomaly regions
DRAIN_LO, DRAIN_HI = 14.5, 17.0
WIND_LO, WIND_HI = 20.5, 28.0
WIND_AMP = 20.0
WIND_OMEGA = 0.055

# Thrust limits and heat safety
MAX_THRUST = 120.0
LOW_THRUST = 90.0
HEAT_SAFE_FRAC = 0.88
VERTICAL_THRUST_CAP = 50.0  # Limit vertical corrections to avoid instability
VERTICAL_VELOCITY_DAMPING = 0.5  # m/s threshold for vertical damping


def _waypoint(x):
    if x < G1_X - 0.1:
        return (G1_X, (G1_Y_MIN + G1_Y_MAX) / 2)
    if x < G2_X - 0.1:
        return (G2_X, (G2_Y_MIN + G2_Y_MAX) / 2)
    return (TARGET_X, TARGET_Y)


def build_agent(sandbox):
    return None  # No agent body needed


def agent_action(sandbox, agent_body, step_count):
    if sandbox.is_overheated():
        return
    pos = sandbox.get_craft_position()
    if pos is None:
        return
    x, y = pos
    heat = sandbox.get_heat()
    overheat_limit = sandbox.get_overheat_limit()
    step_idx = sandbox.get_step_count()

    # Immediate success check
    if TX_MIN <= x <= TX_MAX and TY_MIN <= y <= TY_MAX:
        sandbox.apply_thrust(0.0, 75.0)
        return

    # Thermal-safe thrust scaling
    if heat >= overheat_limit * HEAT_SAFE_FRAC:
        thrust_mag = min(LOW_THRUST, (overheat_limit - heat) * 0.25)
    else:
        thrust_mag = min(MAX_THRUST, (overheat_limit - heat) * 0.35)

    # Drag compensation
    if DRAIN_LO <= x <= DRAIN_HI:
        thrust_mag *= 1.5

    # Get current waypoint
    wx, wy = _waypoint(x)

    # Vertical gate constraint enforcement
    if G1_X - 2.0 <= x <= G1_X + 2.0:
        if y < G1_Y_MIN:
            wy = max(wy, G1_Y_MIN + 0.2)
        elif y > G1_Y_MAX:
            wy = min(wy, G1_Y_MAX - 0.2)
    if G2_X - 2.0 <= x <= G2_X + 2.0:
        if y < G2_Y_MIN:
            wy = max(wy, G2_Y_MIN + 0.2)
        elif y > G2_Y_MAX:
            wy = min(wy, G2_Y_MAX - 0.2)

    # Compute direction to the target
    dx = wx - x
    dy = wy - y
    dist = math.hypot(dx, dy)
    if dist < 1e-6:
        sandbox.apply_thrust(0.0, 75.0)
        return

    ux = dx / dist
    uy = dy / dist
    fx = thrust_mag * ux
    fy = thrust_mag * uy

    # Vertical correction for gate boundaries
    if G1_X - 1.0 <= x <= G1_X + 1.0:
        if y < G1_Y_MIN:
            fy += (G1_Y_MIN - y) * 25.0
        elif y > G1_Y_MAX:
            fy -= (y - G1_Y_MAX) * 25.0
    if G2_X - 1.0 <= x <= G2_X + 1.0:
        if y < G2_Y_MIN:
            fy += (G2_Y_MIN - y) * 25.0
        elif y > G2_Y_MAX:
            fy -= (y - G2_Y_MAX) * 25.0

    # Vertical velocity damping
    vy = agent_body.linearVelocity[1]
    if abs(vy) > VERTICAL_VELOCITY_DAMPING:
        fy -= 0.3 * vy * 10.0  # Oppose vertical motion

    # Wind compensation
    if WIND_LO <= x <= WIND_HI:
        # Predictive wind compensation (feedforward)
        future_steps = 10
        wind_fy = WIND_AMP * sum(math.sin(WIND_OMEGA * (step_idx + i)) for i in range(future_steps)) / future_steps
        fy -= wind_fy

    # Cap total vertical thrust
    if fy > VERTICAL_THRUST_CAP:
        fy = VERTICAL_THRUST_CAP
    elif fy < -VERTICAL_THRUST_CAP:
        fy = -VERTICAL_THRUST_CAP

    # Apply thrust
    sandbox.apply_thrust(fx, fy)
